interactions.query:
query DoctorVerbs($owner: String!, $name: String!, $label0: String!, $label1: String!, $label2: String!, $label3: String!, $label4: String!, $user0: String!) {
  repository(owner: $owner, name: $name) {
    labels(first: 100) { nodes { name } }
    label0: label(name: $label0) { name }
    label1: label(name: $label1) { name }
    label2: label(name: $label2) { name }
    label3: label(name: $label3) { name }
    label4: label(name: $label4) { name }
    user0: assignableUsers(query: $user0, first: 100) { nodes { login } }
  }
}
